{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Tylocrebrine, a polycyclic methoxylated alkaloid with a tertiary amine, showed rapid brain accumulation and an AUCbrain of 2.1 µg·h/mL in mice, directly demonstrating that this alkaloid class can achieve meaningful CNS exposure; noscapine shares the lipophilic polycyclic alkaloid and methoxy/amine features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Coptisine, a methylenedioxy-containing isoquinoline alkaloid, was detected in mouse brain by LC-MS/MS, showing that the methylenedioxy-isoquinoline scaffold can cross the BBB; noscapine contains the same methylenedioxy-isoquinoline substructure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Blonanserin had a human brain/plasma ratio of 3.38 by PET, confirming that a moderately lipophilic aromatic amine with a methoxy group can be a good CNS penetrant; this supports the query's similar passive-diffusion features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "SA4503 showed high, receptor-specific brain uptake in rats, demonstrating that a dimethoxyphenyl-containing amine can achieve robust CNS exposure; noscapine also has a dimethoxyphenyl moiety.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "NPA, an aporphine alkaloid with a tertiary amine, showed good brain penetration in rats and nonhuman primates by PET, supporting CNS access for rigid polycyclic alkaloids like noscapine.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. Noscapine has favorable passive BBB properties, and high-transfer experimental analogues—especially the alkaloids tylocrebrine and coptisine—demonstrate meaningful brain uptake for the same structural class. The single low-uptake record (fesetron) has very low transfer relevance and does not outweigh the supportive evidence.",
  "evidence_gaps": [
    "No direct noscapine brain/plasma or CSF measurement is included in the supplied records.",
    "The brain-tumor/glioma condition may alter BBB integrity and transporter expression, so tumor-specific penetration is not directly evidenced.",
    "Efflux liability of the tertiary amine is inferred but not directly measured in the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

